public class Rational{private final long numerator,denominator;public Rational(long m,long n){numerator=m;denominator=n;}public long numerator(){return numerator;}public long denominator(){return denominator;}public Rational add(Rational b){return new Rational(numerator*b.denominator+b.numerator*denominator,denominator*b.denominator);}public Rational subtract(Rational b){return new Rational(numerator*b.denominator-b.numerator*denominator,denominator*b.denominator);}public Rational multiply(Rational b){return new Rational(numerator*b.numerator,denominator*b.denominator);}public Rational divide(Rational b){return new Rational(numerator*b.denominator,denominator*b.numerator);}public static void transform(Rational[]a){for(int i=0;i+1<a.length;i++)a[i]=a[i].add(a[i+1]);}public String toString(){return numerator+"/"+denominator;}}
